mapper.select:
select from oa_sign_onboard_import_row where task_id in
#{taskId}
order by row_id desc

select r.* from oa_sign_onboard_import_row r inner join oa_sign_onboard_import_batch b on b.batch_id = r.batch_id inner join oa_sign_onboard_data_request d on d.request_id = r.data_request_id and d.row_id = r.row_id and d.employee_id = r.employee_id left join oa_sign_task t on t.task_id = r.task_id and t.package_id = r.package_id left join oa_sign_package p on p.package_id = r.package_id and p.task_id = r.task_id where ( (r.task_id is null and r.package_id is null) or (r.task_id is not null and r.package_id is not null and t.status = 'PENDING_COMPANY' and p.status = 'pending_company' and p.signing_sequence = 'SIGNATURE_FIRST') ) and r.plan_version_id is not null and upper(trim(d.signing_sequence)) = 'SIGNATURE_FIRST' and d.status = 'COMPLETED' and d.signature_request_id is not null and d.signature_sample_hash is not null and d.signature_sample_time is not null and d.signature_sample_bytes is not null and r.status not in ('GENERATING', 'GENERATED', 'SENT', 'PARTIAL_SENT')
and (r.task_id is null or t.assigned_hr_user_id = #{assignedHrUserId})
and b.shop_dept_id in
#{deptId}
order by b.batch_id desc, r.source_row_number asc, r.row_id asc limit #{maxRows}

select  from oa_sign_onboard_import_row
where batch_id = #{batchId}

    and row_id in
    #{rowId}

order by source_row_number, row_id

mapper.update:
update oa_sign_onboard_import_row
set generation_request_id = #{requestId}, version = version + 1, update_time = sysdate()
where row_id = #{rowId} and version = #{expectedVersion}
  and task_id is null and package_id is null and status = 'READY_TO_GENERATE'
  and matched_legal_entity_id = #{legalEntityId}
  and recommended_seal_id = #{sealId}

update oa_sign_onboard_import_row
set generation_request_id = #{requestId}, version = version + 1, update_time = sysdate()
where row_id = #{rowId} and version = #{expectedVersion}
  and task_id = #{taskId} and package_id = #{packageId}
  and data_request_id is not null and status = 'READY_TO_GENERATE'
  and matched_legal_entity_id = #{legalEntityId}
  and recommended_seal_id = #{sealId}

update oa_sign_onboard_import_row
set status = #{status}, version = version + 1, update_time = sysdate()
where row_id = #{rowId} and version = #{expectedVersion}
